CREATE TABLE IF NOT EXISTS exams (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), school_id UUID REFERENCES schools(id), subject_id UUID REFERENCES subjects(id), title TEXT NOT NULL, description TEXT, duration_minutes INT DEFAULT 60, total_marks INT DEFAULT 100, passing_marks INT DEFAULT 40, start_time TIMESTAMPTZ, end_time TIMESTAMPTZ, status TEXT DEFAULT 'draft', created_at TIMESTAMPTZ DEFAULT NOW()); 
